// Run from the project root: node scripts/import-courses.mjs
// Reads data/courses.csv and data/university-info.csv and writes the generated files in data/.
// In both files, "university" may be the exact name shown on the site or its slug (the end of the page URL).
import { readFile, writeFile } from "node:fs/promises";
import { slugify } from "../data/slug.mjs";

function parseCSV(text) {
  const rows = [];
  let row = [], cell = "", quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"' && text[i + 1] === '"') { cell += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cell += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ",") { row.push(cell); cell = ""; }
    else if (ch === "\n") {
      row.push(cell.replace(/\r$/, ""));
      if (row.some((v) => v.trim() !== "")) rows.push(row);
      row = []; cell = "";
    } else cell += ch;
  }
  if (cell.length || row.length) { row.push(cell.replace(/\r$/, "")); rows.push(row); }
  const headers = rows.shift().map((h) => h.trim());
  return rows.map((v) => Object.fromEntries(headers.map((h, i) => [h, (v[i] ?? "").trim()])));
}

async function build({ csv, out, exportName, required, many, label }) {
  const rows = parseCSV(await readFile(new URL(`../data/${csv}`, import.meta.url), "utf8"));
  const result = {};
  let skipped = 0;
  for (const r of rows) {
    if (!r.university || !r[required]) { skipped++; continue; }
    const { university, ...rest } = r;
    const clean = Object.fromEntries(Object.entries(rest).filter(([, v]) => v !== ""));
    const key = slugify(university);
    if (many) (result[key] ??= []).push(clean);
    else result[key] = clean;
  }
  const header = `// Generated by scripts/import-courses.mjs from data/${csv}. Keyed by university slug.\n`;
  await writeFile(
    new URL(`../data/${out}`, import.meta.url),
    `${header}export const ${exportName} = ${JSON.stringify(result, null, 2)};\n`,
  );
  console.log(`${label}: ${rows.length - skipped} rows for ${Object.keys(result).length} universities (${skipped} skipped).`);
}

await build({ csv: "courses.csv", out: "courses-generated.js", exportName: "courses", required: "program", many: true, label: "programmes" });
await build({ csv: "university-info.csv", out: "info-generated.js", exportName: "info", required: "application_portal", many: false, label: "university info" });
